from typing import Optional

from taf.internal.aliasing import aliasing_scope

from taf.sw.graylog.api import GraylogApi, get_version


class graylog:
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    lookup_handler, store = aliasing_scope(name=__name__, lookup_arg="graylog_api", lookup_type=GraylogApi)

    def setup_graylog_api(
        self,
        url: str,
        version: str,
        api_token: str = "",
        username: str = "",
        password: str = "",
        alias: Optional[str] = None,
        default_timeout: float = 30.0,
    ) -> None:
        """Sets up Graylog API client and stores it under given alias.

        Either `api_token` or `username` and `password` must be provided. If both values are
        provided then `api_token` takes precedence over `username` and `password`

        Example::

            Setup Graylog API    http://graylog.example.com:9000
            ...                  ${MY_SECRET_TOKEN}
            ...                  3.3
            ...                  alias=my_graylog

        :param str url: Graylog server URL: https/http + domain or IP address
            + optional port
        :param str version: Graylog version, e.g. "3.3".
        :param str api_token: Token for authentication with API - generated via
            Graylog web interface.
        :param str username: Username for credentials-based authentication.
            Required when API token isn't provided.
        :param str password: Password for credentials-based authentication.
            Required when API token isn't provided.
        :param str alias: Alias by which this session will be retrieved by
            other keywords.
        :param float default_timeout: Timeout for API requests in seconds.
            Default is 30s.
        """
        GraylogApi = get_version(version)
        session = GraylogApi(url, api_token, username, password, default_timeout)
        self.store.add(session, alias)

    @lookup_handler.implicit_lookup
    def query_messages(
        self,
        query: str,
        range_from: int,
        range_seconds: int,
        fields: list[str] = [],
        timeout: Optional[float] = None,
        graylog_api=None,
    ) -> list[dict]:
        """
        Query messages from Graylog server based on the provided query and time range.
        Additionally filters the returned fields based on the ``fields`` parameter.
        If ``fields`` is empty, all fields are returned.

        Example::

            ${messages}=    Query Messages    MR: NetAct    600    300

        :param str query: Graylog search query string.
        :param int range_from: Time offset in whole seconds from the current time to
            start the search.
        :param int range_seconds: Duration in whole seconds for the search range.
        :param list[str] fields: List of fields to include in the response. If empty,
            all fields are included.
        :param float timeout: Timeout for the API request in seconds. If None, uses
            default timeout.
        :param str graylog_api: Alias assigned to the Graylog API session by
            :py:func:`setup_graylog_api`.
        :return: List of messages matching the query within the specified time range.
        :rtype: list[dict]
        """
        assert isinstance(graylog_api, GraylogApi)
        return graylog_api.query_messages(query, range_from, range_seconds, fields, timeout)
